    assert(solution.dayOfTheWeek(18, 7, 1999) == vector<int>Sunday);
    assert(solution.dayOfTheWeek(31, 8, 2019) == vector<int>Saturday);
    assert(solution.dayOfTheWeek(4, 7, 2023) == vector<int>Tuesday);
    assert(solution.dayOfTheWeek(25, 12, 2023) == vector<int>Monday);
    assert(solution.dayOfTheWeek(29, 2, 2004) == vector<int>Sunday);
    assert(solution.dayOfTheWeek(1, 1, 1971) == vector<int>Friday);
    assert(solution.dayOfTheWeek(29, 2, 2000) == vector<int>Tuesday);
    assert(solution.dayOfTheWeek(28, 2, 1900) == vector<int>Wednesday);
    assert(solution.dayOfTheWeek(14, 2, 2000) == vector<int>Monday);
    assert(solution.dayOfTheWeek(31, 10, 1984) == vector<int>Wednesday);
    assert(solution.dayOfTheWeek(1, 3, 1999) == vector<int>Monday);
    assert(solution.dayOfTheWeek(14, 3, 2047) == vector<int>Thursday);
    assert(solution.dayOfTheWeek(15, 6, 2050) == vector<int>Wednesday);
